import{_ as s,o as n,c as e,ag as t}from"./chunks/framework.DEqXEGcv.js";const h=JSON.parse('{"title":"Arc Language Tour","description":"","frontmatter":{},"headers":[],"relativePath":"language-tour.md","filePath":"language-tour.md"}'),p={name:"language-tour.md"};function i(l,a,o,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="arc-language-tour" tabindex="-1">Arc Language Tour <a class="header-anchor" href="#arc-language-tour" aria-label="Permalink to &quot;Arc Language Tour&quot;">​</a></h1><p>A complete walkthrough of every Arc feature with examples.</p><h2 id="variables-bindings" tabindex="-1">Variables &amp; Bindings <a class="header-anchor" href="#variables-bindings" aria-label="Permalink to &quot;Variables &amp; Bindings&quot;">​</a></h2><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let x = 42                      # immutable</span></span>
<span class="line"><span>let mut count = 0                # mutable</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Destructuring</span></span>
<span class="line"><span>let {name, age} = getUser()      # map destructuring</span></span>
<span class="line"><span>let [first, second] = items      # list destructuring</span></span></code></pre></div><p>Immutable by default. Use <code>mut</code> when you need to reassign.</p><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><h3 id="expression-body" tabindex="-1">Expression Body <a class="header-anchor" href="#expression-body" aria-label="Permalink to &quot;Expression Body&quot;">​</a></h3><p>For single-expression functions — no braces, no <code>return</code>:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn add(a, b) =&gt; a + b</span></span>
<span class="line"><span>fn square(x) =&gt; x * x</span></span>
<span class="line"><span>fn greet(name) =&gt; &quot;Hello, {name}!&quot;</span></span></code></pre></div><h3 id="block-body" tabindex="-1">Block Body <a class="header-anchor" href="#block-body" aria-label="Permalink to &quot;Block Body&quot;">​</a></h3><p>For multi-statement functions — last expression is the return value:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn process(data) {</span></span>
<span class="line"><span>  let cleaned = data |&gt; trim |&gt; lowercase</span></span>
<span class="line"><span>  let parsed = parse(cleaned)</span></span>
<span class="line"><span>  parsed  # implicit return</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="closures-lambdas" tabindex="-1">Closures / Lambdas <a class="header-anchor" href="#closures-lambdas" aria-label="Permalink to &quot;Closures / Lambdas&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let double = x =&gt; x * 2</span></span>
<span class="line"><span>let add = (a, b) =&gt; a + b</span></span>
<span class="line"><span>numbers |&gt; map(x =&gt; x * 2)</span></span></code></pre></div><h2 id="pattern-matching" tabindex="-1">Pattern Matching <a class="header-anchor" href="#pattern-matching" aria-label="Permalink to &quot;Pattern Matching&quot;">​</a></h2><p>Arc&#39;s most powerful feature. Replaces if/else chains, switch statements, and type checks:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Value matching</span></span>
<span class="line"><span>match n {</span></span>
<span class="line"><span>  0 =&gt; &quot;zero&quot;,</span></span>
<span class="line"><span>  1 | 2 =&gt; &quot;small&quot;,</span></span>
<span class="line"><span>  n if n &lt; 0 =&gt; &quot;negative&quot;,</span></span>
<span class="line"><span>  n =&gt; &quot;other: {n}&quot;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Wildcard / binding</span></span>
<span class="line"><span>match items {</span></span>
<span class="line"><span>  [] =&gt; &quot;empty&quot;,</span></span>
<span class="line"><span>  [x] =&gt; &quot;single: {x}&quot;,</span></span>
<span class="line"><span>  _ =&gt; &quot;multiple items&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="pipeline-operator" tabindex="-1">Pipeline Operator <a class="header-anchor" href="#pipeline-operator" aria-label="Permalink to &quot;Pipeline Operator&quot;">​</a></h2><p>Read left-to-right instead of inside-out:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Without pipeline (nested)</span></span>
<span class="line"><span>print(join(sort(filter(words, w =&gt; len(w) &gt; 3)), &quot;, &quot;))</span></span>
<span class="line"><span></span></span>
<span class="line"><span># With pipeline (linear)</span></span>
<span class="line"><span>words</span></span>
<span class="line"><span>  |&gt; filter(w =&gt; len(w) &gt; 3)</span></span>
<span class="line"><span>  |&gt; sort</span></span>
<span class="line"><span>  |&gt; join(&quot;, &quot;)</span></span>
<span class="line"><span>  |&gt; print</span></span></code></pre></div><p>Pipelines pass the left value as the first argument to the right function.</p><h2 id="collections" tabindex="-1">Collections <a class="header-anchor" href="#collections" aria-label="Permalink to &quot;Collections&quot;">​</a></h2><h3 id="lists" tabindex="-1">Lists <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;Lists&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let nums = [1, 2, 3, 4, 5]</span></span>
<span class="line"><span>let first = nums[0]</span></span>
<span class="line"><span>let combined = [1, 2] ++ [3, 4]    # concat with ++</span></span></code></pre></div><h3 id="maps" tabindex="-1">Maps <a class="header-anchor" href="#maps" aria-label="Permalink to &quot;Maps&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let user = {name: &quot;Alice&quot;, age: 30}</span></span>
<span class="line"><span>let name = user.name                 # dot access</span></span>
<span class="line"><span>let age = user[&quot;age&quot;]                # bracket access</span></span>
<span class="line"><span>let shorthand = {name, age}          # same as {name: name, age: age}</span></span></code></pre></div><h3 id="ranges" tabindex="-1">Ranges <a class="header-anchor" href="#ranges" aria-label="Permalink to &quot;Ranges&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let r = 1..10                        # 1 to 9</span></span>
<span class="line"><span>let digits = 0..10                   # 0 to 9</span></span></code></pre></div><h3 id="comprehensions" tabindex="-1">Comprehensions <a class="header-anchor" href="#comprehensions" aria-label="Permalink to &quot;Comprehensions&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let evens = [x * 2 for x in 1..10]</span></span>
<span class="line"><span>let squares = [x * x for x in 1..10 if x % 2 == 0]</span></span></code></pre></div><h2 id="string-interpolation" tabindex="-1">String Interpolation <a class="header-anchor" href="#string-interpolation" aria-label="Permalink to &quot;String Interpolation&quot;">​</a></h2><p>Expressions inside <code>{}</code> in strings:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let name = &quot;Arc&quot;</span></span>
<span class="line"><span>let msg = &quot;Hello, {name}!&quot;</span></span>
<span class="line"><span>let result = 2 + 3</span></span>
<span class="line"><span>let math = &quot;2 + 3 = {result}&quot;</span></span>
<span class="line"><span>let nested = &quot;User: {user.name} ({user.age})&quot;</span></span></code></pre></div><blockquote><p><strong>Note:</strong> <code>{expr}</code> only interpolates when <code>expr</code> starts with a letter or underscore. <code>{42}</code> or <code>{2 + 3}</code> stays literal — assign to a variable first.</p></blockquote><p>Use <code>\\{</code> to escape braces in strings: <code>&quot;literal \\{braces\\}&quot;</code></p><h2 id="type-system" tabindex="-1">Type System <a class="header-anchor" href="#type-system" aria-label="Permalink to &quot;Type System&quot;">​</a></h2><h3 id="primitive-types" tabindex="-1">Primitive Types <a class="header-anchor" href="#primitive-types" aria-label="Permalink to &quot;Primitive Types&quot;">​</a></h3><p><code>Int</code>, <code>Float</code>, <code>String</code>, <code>Bool</code>, <code>Nil</code>, <code>Any</code></p><h3 id="type-definitions" tabindex="-1">Type Definitions <a class="header-anchor" href="#type-definitions" aria-label="Permalink to &quot;Type Definitions&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type User = {name: String, age: Int, email: Email}</span></span>
<span class="line"><span>type Result&lt;T&gt; = Ok(T) | Err(String)</span></span>
<span class="line"><span>type Handler = (Request) -&gt; Response</span></span></code></pre></div><h3 id="semantic-constrained-types" tabindex="-1">Semantic / Constrained Types <a class="header-anchor" href="#semantic-constrained-types" aria-label="Permalink to &quot;Semantic / Constrained Types&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>type Email = String matching /^[^@]+@[^@]+\\.[^@]+$/</span></span>
<span class="line"><span>type Age = Int where x =&gt; x &gt;= 0 and x &lt;= 150</span></span></code></pre></div><p>Types carry meaning, not just structure. Validation is built into the type.</p><h2 id="tool-calls" tabindex="-1">Tool Calls <a class="header-anchor" href="#tool-calls" aria-label="Permalink to &quot;Tool Calls&quot;">​</a></h2><p>First-class API and tool integration with <code>@</code>:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># HTTP methods</span></span>
<span class="line"><span>let user = @GET &quot;api/users/{id}&quot;</span></span>
<span class="line"><span>@POST &quot;api/users&quot; {name: &quot;Arc&quot;, role: &quot;agent&quot;}</span></span>
<span class="line"><span>@PUT &quot;api/users/{id}&quot; updated_user</span></span>
<span class="line"><span>@DELETE &quot;api/users/{id}&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Custom tools</span></span>
<span class="line"><span>let answer = @llm(&quot;Summarize: {text}&quot;)</span></span>
<span class="line"><span>let files = @shell(&quot;ls -la&quot;)</span></span></code></pre></div><p>No imports, no client setup, no serialization. Just call it.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><p>Arc uses map-based results for error handling:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fn safe_divide(a, b) {</span></span>
<span class="line"><span>  if b == 0 { {ok: false, error: &quot;division by zero&quot;} }</span></span>
<span class="line"><span>  else { {ok: true, value: a / b} }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let result = safe_divide(10, 3)</span></span>
<span class="line"><span>if result.ok {</span></span>
<span class="line"><span>  print(&quot;Result: {result.value}&quot;)</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>  print(&quot;Error: {result.error}&quot;)</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="async-concurrency" tabindex="-1">Async / Concurrency <a class="header-anchor" href="#async-concurrency" aria-label="Permalink to &quot;Async / Concurrency&quot;">​</a></h2><h3 id="auto-await" tabindex="-1">Auto-Await <a class="header-anchor" href="#auto-await" aria-label="Permalink to &quot;Auto-Await&quot;">​</a></h3><p>Most async calls are auto-awaited — no ceremony:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let user = fetchUser(id)   # auto-awaited</span></span></code></pre></div><h3 id="parallel-fetch" tabindex="-1">Parallel Fetch <a class="header-anchor" href="#parallel-fetch" aria-label="Permalink to &quot;Parallel Fetch&quot;">​</a></h3><p>Fetch multiple resources concurrently:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let [users, posts, stats] = fetch [</span></span>
<span class="line"><span>  @GET &quot;api/users&quot;,</span></span>
<span class="line"><span>  @GET &quot;api/posts&quot;,</span></span>
<span class="line"><span>  @GET &quot;api/stats&quot;</span></span>
<span class="line"><span>]</span></span></code></pre></div><h3 id="explicit-async" tabindex="-1">Explicit Async <a class="header-anchor" href="#explicit-async" aria-label="Permalink to &quot;Explicit Async&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let task = async { heavyComputation() }</span></span>
<span class="line"><span>let result = await task</span></span></code></pre></div><h2 id="control-flow" tabindex="-1">Control Flow <a class="header-anchor" href="#control-flow" aria-label="Permalink to &quot;Control Flow&quot;">​</a></h2><h3 id="if-el-expression" tabindex="-1">If / El (Expression) <a class="header-anchor" href="#if-el-expression" aria-label="Permalink to &quot;If / El (Expression)&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>let label = if count &gt; 0 { &quot;active&quot; } else { &quot;empty&quot; }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if ready {</span></span>
<span class="line"><span>  go()</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>  wait()</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="for-loops" tabindex="-1">For Loops <a class="header-anchor" href="#for-loops" aria-label="Permalink to &quot;For Loops&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>for item in items { process(item) }</span></span>
<span class="line"><span>for i in 0..10 { print(i) }</span></span>
<span class="line"><span>for user in users { print(&quot;{user.name}: {user.age}&quot;) }</span></span></code></pre></div><h3 id="do-loops" tabindex="-1">Do Loops <a class="header-anchor" href="#do-loops" aria-label="Permalink to &quot;Do Loops&quot;">​</a></h3><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>do {</span></span>
<span class="line"><span>  let input = readline()</span></span>
<span class="line"><span>} until input == &quot;quit&quot;</span></span></code></pre></div><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use std/io</span></span>
<span class="line"><span>use std/http: GET, POST</span></span>
<span class="line"><span>use mylib/utils: *</span></span></code></pre></div><p><code>use</code> with <code>/</code> paths and <code>:</code> for selective imports. <code>pub</code> marks public exports:</p><div class="language-arc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">arc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pub fn greet(name) =&gt; &quot;Hello, {name}!&quot;</span></span></code></pre></div><hr><p><strong>Next:</strong> See the <a href="/stdlib-tutorial">Standard Library Tutorial</a> for hands-on examples, or the <a href="/stdlib-reference">Standard Library Reference</a> for full API docs.</p>`,72)])])}const g=s(p,[["render",i]]);export{h as __pageData,g as default};
